import { Directory, File, Paths } from 'expo-file-system';

import type { ReminderSettings } from '../domain/types';

/**
 * File bridge between the app and the native closed-app tap logger
 * (NfcTapActivity, generated by plugins/withNfcLaunchIntent.js).
 *
 * The native side must never open HydraTap's SQLite database: it would use Android's
 * system SQLite while the app uses expo-sqlite's bundled SQLite, and two SQLite
 * libraries in one process can't coordinate file locks (stale reads, failed writes).
 * Instead:
 *   - app → native: `hydratap-bridge/state.json` (sticker, goal, today's total…)
 *   - native → app: one file per tap in `hydratap-bridge/taps/`, imported into
 *     SQLite (then deleted) whenever the app starts or returns to the foreground.
 * Paths.document is Android's filesDir, which NfcTapActivity uses too.
 */

export interface BridgeState {
  v: 1;
  onboarded: boolean;
  stickerUid: string | null;
  /** Secret of the link written to stickers by builds 4–6 (still accepted). */
  linkKey: string;
  goalMl: number;
  scanAmountMl: number;
  reminders: ReminderSettings;
  /** Local day (YYYY-MM-DD) that todayTotalMl belongs to. */
  day: string;
  todayTotalMl: number;
  /** Latest sticker-tap timestamp already in the database (duplicate protection). */
  lastScanAt: number | null;
}

export interface PendingTap {
  at: number;
  amountMl: number;
  goalMl: number;
  tagId: string | null;
}

const bridgeDir = () => new Directory(Paths.document, 'hydratap-bridge');
const tapsDir = () => new Directory(bridgeDir(), 'taps');

let lastWritten = '';

export async function writeBridgeState(state: BridgeState): Promise<void> {
  const json = JSON.stringify(state);
  if (json === lastWritten) return;
  const dir = bridgeDir();
  if (!dir.exists) dir.create({ intermediates: true });
  // Write a temp file and move it into place so the native side never reads half a file.
  const tmp = new File(dir, 'state.json.tmp');
  tmp.create({ overwrite: true });
  await tmp.write(json);
  await tmp.move(new File(dir, 'state.json'), { overwrite: true });
  lastWritten = json;
}

/**
 * Imports taps logged while the app was closed. `insert` must persist the tap and
 * be idempotent; the tap file is deleted only after it succeeds.
 */
export async function importPendingTaps(insert: (tap: PendingTap) => Promise<void>): Promise<number> {
  const dir = tapsDir();
  if (!dir.exists) return 0;
  const files = dir
    .list()
    .filter((f): f is File => f instanceof File && f.name.endsWith('.json'))
    .sort((a, b) => a.name.localeCompare(b.name));
  let imported = 0;
  for (const f of files) {
    try {
      const tap = JSON.parse(await f.text()) as PendingTap;
      if (typeof tap.at === 'number' && tap.amountMl > 0) {
        await insert(tap);
        imported++;
      }
      f.delete();
    } catch {
      // Leave unreadable / failed files for the next attempt.
    }
  }
  return imported;
}
